INSERT INTO `resources` (`category_id`,`main_category_id`,`subcategory_id`,`title`,`title_ar`,`slug`,`resource_type`,`tech_stack`,`tech_stack_ar`,`description`,`description_ar`,`features`,`features_ar`,`short_description`,`short_description_ar`,`preview_image`,`detail_image`,`screenshots`,`featured`,`is_free`,`license_type`,`price`,`version`,`license`,`downloads_count`,`rating`,`reviews_count`,`published_at`,`status`,`demo_url`,`seo_title`,`seo_description`,`seo_title_ar`,`seo_description_ar`,`seo_keywords`,`image_alt`,`image_alt_ar`,`canva_design_id`,`canva_url`,`source_url`,`external_url`,`gallery_status`,`created_at`,`updated_at`) VALUES ((SELECT id FROM categories WHERE slug='canva-templates' LIMIT 1),(SELECT id FROM main_categories WHERE slug='design-templates' LIMIT 1),(SELECT id FROM subcategories WHERE slug='legal-finance' LIMIT 1),'Lawyers 1 — Editable Canva Template','قالب المحاماة والخدمات القانونية 1 قابل للتعديل على Canva','lawyers-1','design','Canva','Canva','<p><strong>Lawyers 1</strong> is an editable Canva template created for legal professionals, consultants and finance brands. It is suitable for branded social-media content, promotional announcements, service highlights and recurring marketing campaigns.</p><p>Open the original Canva design from EzyTemplate and personalize the copy, colors, fonts, photos and brand elements. The template is intended to give you a faster starting point while keeping the final content consistent with your own brand.</p><p>This EzyTemplate listing includes a categorized preview gallery, SEO-ready metadata and a direct source link to the Canva design. Always review the source design and Canva licensing terms before commercial redistribution.</p>','<p><strong>قالب المحاماة والخدمات القانونية 1 قابل للتعديل على Canva</strong> مخصص لـالمحامين والمستشارين والعلامات المالية. يمكن استخدامه كنقطة بداية سريعة لإنشاء منشورات سوشيال ميديا، عروض، إعلانات، وتعريف بالخدمات بشكل متناسق مع هوية النشاط.</p><p>يمكن فتح التصميم الأصلي على Canva وتعديل النصوص والألوان والخطوط والصور وعناصر الهوية بما يناسب العلامة التجارية. الهدف هو تقليل وقت التصميم مع الحفاظ على مرونة التخصيص.</p><p>تتضمن صفحة EzyTemplate معرض معاينة منظم وبيانات SEO ورابط المصدر الأصلي على Canva. يجب مراجعة شروط الترخيص الخاصة بالمصدر وCanva قبل أي إعادة توزيع تجاري.</p>','["Editable directly in Canva", "Customize text, colors, fonts, photos and branding", "Organized under Canva Templates → Legal & Finance", "Suitable for social posts, promotions and announcements", "Direct link to the original Canva source design", "SEO-ready EzyTemplate listing with preview gallery"]','["قابل للتعديل مباشرة على Canva", "إمكانية تعديل النصوص والألوان والخطوط والصور والهوية", "مصنف داخل قوالب Canva ← القانون والمال", "مناسب للمنشورات والعروض والإعلانات", "رابط مباشر إلى تصميم Canva الأصلي", "صفحة EzyTemplate مجهزة لبيانات SEO ومعرض الصور"]','A clean editable Canva template for legal professionals, consultants and finance brands, designed for branded social posts, promotions, announcements and service marketing.','قالب Canva نظيف قابل للتعديل ومناسب لـالمحامين والمستشارين والعلامات المالية، لاستخدامه في المنشورات الترويجية والعروض والإعلانات ومحتوى الهوية البصرية.','/storage/canva/lawyers-1/cover.png','/storage/canva/lawyers-1/sample-1.png','["/storage/canva/lawyers-1/sample-1.png", "/storage/canva/lawyers-1/sample-2.png", "/storage/canva/lawyers-1/sample-3.png"]',1,1,'external',0,'1.0.0','External Canva source — use subject to Canva/source license terms',0,0.0,0,'2026-09-13 18:00:00','published','https://www.canva.com/design/DAEwJ9SBQic/KPXuPC3rwU5RS-PtR0M1UQ/view?mode=preview','Lawyers 1 Canva Template | EzyTemplate','Edit Lawyers 1 in Canva. Clean template for legal professionals, consultants and finance brands, ideal for branded social posts, promotions and digital marke…','قالب المحاماة والخدمات القانونية 1 قابل للتعديل على Canva |…','حمّل وخصص قالب المحاماة والخدمات القانونية 1 قابل للتعديل على Canva. قالب نظيف مناسب لـالمحامين والمستشارين 